import { test } from "node:test";
import assert from "node:assert/strict";
import { AppointmentService } from "../src/clinic/service.ts";
import { appointmentHandlers, type Req } from "../src/clinic/handlers.ts";
import { coverDay } from "../src/clinic/coverage.ts";
import { dayOf, type Appointment, type AppointmentRepo } from "../src/clinic/types.ts";

function setup() {
    const rows = new Map<string, Appointment>();
    const repo: AppointmentRepo = {
        get: async (id) => rows.get(id) ?? null,
        listForClinician: async (clinicianId, day) => [...rows.values()].filter((a) => a.clinicianId === clinicianId && dayOf(a.start) === day),
        save: async (a) => void rows.set(a.id, { ...a }),
    };
    let n = 0;
    const service = new AppointmentService(repo, () => `a${++n}`);
    const api = appointmentHandlers(service, repo);
    const as = (patientId: string, body: Record<string, unknown> = {}, params: Record<string, string> = {}): Req => ({ caller: { patientId }, params, body });
    const book = (patientId: string, clinicianId: string, start: string, minutes = 30) => api.book(as(patientId, { clinicianId, start, minutes }));
    return { rows, repo, service, api, as, book };
}

test("a patient books a free slot", async () => {
    const { book, rows } = setup();
    const res = await book("p1", "dr-osei", "2026-12-01T10:00:00Z");
    assert.equal(res.status, 201);
    assert.equal(rows.get("a1")?.clinicianId, "dr-osei");
});

test("booking a slot the clinician already has is a 409", async () => {
    const { book } = setup();
    await book("p1", "dr-osei", "2026-12-01T10:00:00Z");
    const res = await book("p2", "dr-osei", "2026-12-01T10:15:00Z");
    assert.equal(res.status, 409);
});

test("a patient moves their appointment to another free time", async () => {
    const { book, api, as, rows } = setup();
    await book("p1", "dr-osei", "2026-12-01T10:00:00Z");
    const res = await api.reschedule(as("p1", { start: "2026-12-01T14:30:00Z" }, { id: "a1" }));
    assert.equal(res.status, 200);
    assert.equal(rows.get("a1")?.start.toISOString(), "2026-12-01T14:30:00.000Z");
});

test("rescheduling onto another patient's slot is refused and leaves the appointment where it was", async () => {
    const { book, api, as, rows } = setup();
    await book("p1", "dr-osei", "2026-12-01T10:00:00Z");
    await book("p2", "dr-osei", "2026-12-01T11:00:00Z");
    const res = await api.reschedule(as("p1", { start: "2026-12-01T11:00:00Z" }, { id: "a1" }));
    console.log("reschedule onto a taken slot ->", res);
    assert.equal(res.status, 409);
    assert.equal(rows.get("a1")?.start.toISOString(), "2026-12-01T10:00:00.000Z");
});

test("rescheduling outside opening hours or off the 15-minute grid is a 422", async () => {
    const { book, api, as, rows } = setup();
    await book("p1", "dr-osei", "2026-12-01T10:00:00Z");
    assert.equal((await api.reschedule(as("p1", { start: "2026-12-01T16:45:00Z" }, { id: "a1" }))).status, 422);
    assert.equal((await api.reschedule(as("p1", { start: "2026-12-01T12:10:00Z" }, { id: "a1" }))).status, 422);
    assert.equal(rows.get("a1")?.start.toISOString(), "2026-12-01T10:00:00.000Z");
});

test("a patient can't see or change someone else's appointment", async () => {
    const { book, api, as } = setup();
    await book("p1", "dr-osei", "2026-12-01T10:00:00Z");
    assert.equal((await api.reschedule(as("p2", { start: "2026-12-01T13:00:00Z" }, { id: "a1" }))).status, 404);
    assert.equal((await api.cancel(as("p2", {}, { id: "a1" }))).status, 404);
    assert.equal((await api.reschedule(as("p1", { start: "not a date" }, { id: "a1" }))).status, 400);
});

test("cover for a sick clinician only takes the appointments that fit their day", async () => {
    const { book, api, as, service, repo } = setup();
    await book("p1", "dr-osei", "2026-12-01T09:00:00Z"); // a1
    await book("p2", "dr-osei", "2026-12-01T11:00:00Z"); // a2
    await book("p3", "dr-lind", "2026-12-01T13:00:00Z"); // a3, dr-lind's own patient
    await book("p4", "dr-osei", "2026-12-01T15:00:00Z"); // a4
    // p4 tries to squeeze in next to p2, then dr-osei's day is handed over
    await api.reschedule(as("p4", { start: "2026-12-01T11:15:00Z" }, { id: "a4" }));
    const report = await coverDay(service, repo, "dr-osei", "dr-lind", "2026-12-01");
    assert.deepEqual(report, { moved: ["a1", "a2", "a4"], unmoved: [] });
    const lind = (await repo.listForClinician("dr-lind", "2026-12-01")).map((a) => a.start.toISOString().slice(11, 16)).sort();
    assert.deepEqual(lind, ["09:00", "11:00", "13:00", "15:00"]);
});
